 internal void RefreshAccounts(){accountPanel.Children.Clear();accountPage=Math.Clamp(accountPage,0,Math.Max(0,accounts.Count-1));foreach(var account in accounts.Skip(accountPage).Take(1).ToList()){var row=new DockPanel{LastChildFill=true};var remove=IconButton("\uE711","Desconectar "+account.Email,()=>{accounts.Remove(account);main.AccountsChanged();RefreshAccounts();RefreshCalendars();});DockPanel.SetDock(remove,Dock.Right);row.Children.Add(remove);var caption=new StackPanel();var accountName=MainWindow.Label(account.Email,12,true);accountName.TextWrapping=TextWrapping.NoWrap;accountName.TextTrimming=TextTrimming.CharacterEllipsis;accountName.ToolTip=account.Email;caption.Children.Add(accountName);caption.Children.Add(MainWindow.Label(account.Provider=="Google"?"Google":account.Provider=="LocalIcs"?"Arquivo iCalendar":"Assinatura iCalendar",10));row.Children.Add(caption);accountPanel.Children.Add(new Border{CornerRadius=new CornerRadius(8),Padding=new Thickness(8),Margin=new Thickness(0,3,0,5),Background=new SolidColorBrush(Color.FromArgb(18,128,128,128)),Child=row});}if(accounts.Count>1)accountPanel.Children.Add(Pager(accountPage,accounts.Count,page=>{accountPage=page;RefreshAccounts();}));if(accounts.Count==0)accountPanel.Children.Add(MainWindow.Label("Nenhuma conta conectada",12));}
