 void RefreshCalendars(){var available=main.snapshots.Values.SelectMany(s=>s.Calendars).GroupBy(c=>c.Id).Select(g=>g.First()).ToList();var signature=accounts.Count+"|"+string.Join("|",available.Select(c=>c.Id+":"+c.Name))+"|"+string.Join("|",settings.HiddenCalendars);if(signature==calendarSignature)return;calendarSignature=signature;calendarPanel.Children.Clear();if(available.Count==0)calendarPanel.Children.Add(MainWindow.Label(accounts.Count==0?"Conecte um calendário.":"Aguardando atualização.",12));calendarPage=Math.Clamp(calendarPage,0,Math.Max(0,(available.Count-1)/4));foreach(var calendar in available.Skip(calendarPage*4).Take(4)){var check=Check("\uE787",calendar.Name,!settings.HiddenCalendars.Contains(calendar.Id));check.MaxHeight=42;check.ToolTip=calendar.Name;check.Click+=(_,_)=>{settings.HiddenCalendars.Remove(calendar.Id);if(check.IsChecked!=true)settings.HiddenCalendars.Add(calendar.Id);main.Persist();main.Render();};calendarPanel.Children.Add(check);}if(available.Count>4)calendarPanel.Children.Add(Pager(calendarPage,(available.Count+3)/4,page=>{calendarPage=page;calendarSignature="";RefreshCalendars();}));}
